<?php
require_auth(['admin']);
$pageTitle = 'Quản lý Leads';
$leads = rows('SELECT l.*, al.code, u.name AS referrer, c.title AS campaign_title FROM leads l LEFT JOIN affiliate_links al ON al.id = l.affiliate_id LEFT JOIN users u ON u.id = al.user_id LEFT JOIN campaigns c ON c.id = al.campaign_id ORDER BY l.id DESC');
?>
<div class="row g-4 metric-grid mb-4"><div class="col-sm-4"><article class="metric-card"><span class="metric-icon coral"><i class="bi bi-person-plus-fill"></i></span><div><p>Tổng leads</p><h3><?= count($leads) ?></h3><small>Toàn hệ thống</small></div></article></div><div class="col-sm-4"><article class="metric-card"><span class="metric-icon green"><i class="bi bi-patch-check-fill"></i></span><div><p>Đạt chuẩn</p><h3><?= (int) scalar("SELECT COUNT(*) FROM leads WHERE status = 'qualified'") ?></h3><small>Đã xác minh</small></div></article></div><div class="col-sm-4"><article class="metric-card"><span class="metric-icon blue"><i class="bi bi-link-45deg"></i></span><div><p>Nguồn affiliate</p><h3><?= (int) scalar('SELECT COUNT(DISTINCT affiliate_id) FROM leads') ?></h3><small>Link tạo chuyển đổi</small></div></article></div></div>
<section class="panel-card"><div class="panel-head"><div><p class="eyebrow">DỮ LIỆU TUYỂN SINH</p><h3>Danh sách lead</h3></div><button class="btn btn-light border"><i class="bi bi-download"></i> Xuất CSV</button></div><div class="table-responsive"><table class="table clean-table"><thead><tr><th>Học sinh</th><th>Liên hệ</th><th>Ngành quan tâm</th><th>Người giới thiệu</th><th>Chiến dịch</th><th>Trạng thái</th></tr></thead><tbody><?php foreach ($leads as $lead): ?><tr><td><strong><?= e($lead['full_name']) ?></strong><small class="d-block text-muted"><?= date('d/m/Y H:i', strtotime($lead['created_at'])) ?></small></td><td><?= e($lead['phone']) ?><small class="d-block text-muted"><?= e($lead['email']) ?></small></td><td><?= e($lead['major']) ?></td><td><?= e($lead['referrer'] ?: 'Trực tiếp') ?><small class="d-block text-muted"><?= e($lead['code']) ?></small></td><td><?= e($lead['campaign_title'] ?: '-') ?></td><td><span class="badge text-bg-<?= e(status_badge($lead['status'])) ?>-subtle"><?= e($lead['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></section>
